const CACHE_NAME="printing-app-v1",ASSETS_TO_CACHE=["/","/index.html","/app.bundle.js","/runtime.bundle.js","/manifest.json"];self.addEventListener("install",e=>{e.waitUntil(caches.open(CACHE_NAME).then(e=>(console.log("Cache opened"),e.addAll(ASSETS_TO_CACHE))))}),self.addEventListener("activate",e=>{e.waitUntil(caches.keys().then(e=>Promise.all(e.map(e=>{if(e!==CACHE_NAME)return caches.delete(e)}))))}),self.addEventListener("fetch",e=>{e.respondWith(caches.match(e.request).then(t=>t||fetch(e.request)).catch(()=>new Response("Offline mode: No cached data available")))});